package arraylist;

import java.util.ArrayList;
import java.util.List;

public class Size {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		List obj=new ArrayList();//syntax of list
		//add elements to list
		obj.add(5);
		obj.add(3.3f);
		obj.add("karthika");
		obj.add("aswathy");
		obj.add("asheena");
		System.out.println(obj.size());// size denoted as length
	}

}
